import React, {
  useEffect,
  useMemo,
  useState,
} from "react";

import "./MissionControl.css";

const API_URL =
  "https://space-debris-tracker-api-t9n9.onrender.com";

const MissionControl = ({
  onTrackEvent,
}) => {
  const [events, setEvents] =
    useState([]);

  const [loading, setLoading] =
    useState(true);

  const [selectedEvent, setSelectedEvent] =
    useState(null);

  const [error, setError] =
    useState(null);

  /*
  =========================================================
  LOAD AI COLLISION PREDICTIONS
  =========================================================
  */

  const loadCollisions = async () => {
    try {
      setLoading(true);
      setError(null);

      const response =
        await fetch(
          `${API_URL}/api/ai/collisions?minutes=180&threshold=100`
        );

      if (!response.ok) {
        throw new Error(
          `AI Collision API returned ${response.status}`
        );
      }

      const data =
        await response.json();

      if (
        !data.success ||
        !Array.isArray(data.results)
      ) {
        throw new Error(
          "Invalid AI collision response."
        );
      }

      setEvents(
        data.results
      );
    } catch (err) {
      console.error(
        "AI collision prediction error:",
        err
      );

      setError(
        "Unable to load AI collision predictions."
      );

      setEvents([]);
    } finally {
      setLoading(false);
    }
  };

  /*
  =========================================================
  AUTO REFRESH
  =========================================================
  */

  useEffect(() => {
    loadCollisions();

    const interval =
      setInterval(
        loadCollisions,
        60000
      );

    return () =>
      clearInterval(interval);
  }, []);

  /*
  =========================================================
  AI PREDICTION STATISTICS
  =========================================================
  */

  const statistics =
    useMemo(() => {
      return {
        total:
          events.length,

        critical:
          events.filter(
            (event) =>
              event.aiPrediction
                ?.predictionLevel ===
              "CRITICAL"
          ).length,

        high:
          events.filter(
            (event) =>
              event.aiPrediction
                ?.predictionLevel ===
              "HIGH"
          ).length,

        medium:
          events.filter(
            (event) =>
              event.aiPrediction
                ?.predictionLevel ===
              "MEDIUM"
          ).length,

        low:
          events.filter(
            (event) =>
              event.aiPrediction
                ?.predictionLevel ===
              "LOW"
          ).length,
      };
    }, [events]);

  /*
  =========================================================
  RISK CLASS
  =========================================================
  */

  const getRiskClass =
    (risk) => {
      switch (risk) {
        case "CRITICAL":
          return "risk-critical";

        case "HIGH":
          return "risk-high";

        case "MEDIUM":
          return "risk-medium";

        default:
          return "risk-low";
      }
    };

  /*
  =========================================================
  TIME FORMAT
  =========================================================
  */

  const formatTimeToTCA =
    (seconds) => {
      if (
        !Number.isFinite(seconds)
      ) {
        return "--";
      }

      if (seconds <= 0) {
        return "NOW";
      }

      const minutes =
        Math.floor(
          seconds / 60
        );

      if (minutes < 60) {
        return `${minutes} min`;
      }

      const hours =
        Math.floor(
          minutes / 60
        );

      const remaining =
        minutes % 60;

      return `${hours}h ${remaining}m`;
    };

  /*
  =========================================================
  DISTANCE FORMAT
  =========================================================
  */

  const formatDistance =
    (distance) => {
      if (
        !Number.isFinite(distance)
      ) {
        return "--";
      }

      return `${distance.toFixed(
        2
      )} km`;
    };

  /*
  =========================================================
  TRACK EVENT
  =========================================================

  IMPORTANT:
  Existing Track Event behaviour
  remains unchanged.
  */

  const trackEvent =
    (event) => {
      setSelectedEvent(event);

      if (onTrackEvent) {
        onTrackEvent(event);
      }
    };

  /*
  =========================================================
  AI CONFIDENCE FORMAT
  =========================================================
  */

  const formatConfidence =
    (confidence) => {
      if (
        !Number.isFinite(
          confidence
        )
      ) {
        return "--";
      }

      return `${confidence}%`;
    };

  /*
  =========================================================
  RENDER
  =========================================================
  */

  return (
    <div className="mission-control">

      {/* =================================================
          HEADER
          ================================================= */}

      <div className="mission-header">

        <div>

          <div className="mission-title">
            AI COLLISION INTELLIGENCE
          </div>

          <div className="mission-subtitle">
            SGP4 + AI COLLISION PREDICTION ENGINE
          </div>

        </div>

        <button
          className="refresh-button"
          onClick={loadCollisions}
        >
          REFRESH
        </button>

      </div>


      {/* =================================================
          AI SUMMARY
          ================================================= */}

      <div className="risk-summary">

        <div className="summary-card">

          <span>
            PREDICTIONS
          </span>

          <strong>
            {statistics.total}
          </strong>

        </div>


        <div className="summary-card critical">

          <span>
            CRITICAL
          </span>

          <strong>
            {statistics.critical}
          </strong>

        </div>


        <div className="summary-card high">

          <span>
            HIGH
          </span>

          <strong>
            {statistics.high}
          </strong>

        </div>


        <div className="summary-card medium">

          <span>
            MEDIUM
          </span>

          <strong>
            {statistics.medium}
          </strong>

        </div>

      </div>


      {/* =================================================
          LOW SUMMARY
          ================================================= */}

      <div className="risk-summary">

        <div className="summary-card low">

          <span>
            LOW
          </span>

          <strong>
            {statistics.low}
          </strong>

        </div>

      </div>


      {/* =================================================
          LOADING
          ================================================= */}

      {loading && (
        <div className="mission-status">

          AI ANALYZING ORBITAL TRAJECTORIES...

        </div>
      )}


      {/* =================================================
          ERROR
          ================================================= */}

      {error && (
        <div className="mission-error">

          {error}

        </div>
      )}


      {/* =================================================
          EMPTY
          ================================================= */}

      {!loading &&
        !error &&
        events.length === 0 && (
          <div className="mission-status">

            NO AI COLLISION PREDICTIONS DETECTED

          </div>
        )}


      {/* =================================================
          COLLISION LIST
          ================================================= */}

      <div className="collision-list">

        {events.map(
          (event, index) => {

            const approach =
              event.closestApproach ||
              {};

            const object1 =
              event.object1 ||
              {};

            const object2 =
              event.object2 ||
              {};

            const ai =
              event.aiPrediction ||
              {};

            const features =
              ai.features ||
              {};

            /*
            -----------------------------------------------
            AI LEVEL
            -----------------------------------------------
            */

            const predictionLevel =
              ai.predictionLevel ||
              approach.riskLevel ||
              "UNKNOWN";


            return (
              <div
                className={`collision-card ${
                  selectedEvent === event
                    ? "selected"
                    : ""
                }`}
                key={`${object1.noradId}-${object2.noradId}-${index}`}
              >

                {/* =========================================
                    AI HEADER
                    ========================================= */}

                <div className="collision-top">

                  <div
                    className={`risk-badge ${getRiskClass(
                      predictionLevel
                    )}`}
                  >
                    {predictionLevel}
                  </div>


                  <div className="risk-score">

                    AI SCORE{" "}

                    {ai.predictionScore ??
                      "--"}

                  </div>

                </div>


                {/* =========================================
                    OBJECTS
                    ========================================= */}

                <div className="object-row">

                  <div className="object">

                    <div className="object-name">

                      {object1.name ||
                        "UNKNOWN OBJECT"}

                    </div>

                    <div className="norad">

                      NORAD{" "}

                      {object1.noradId ||
                        "--"}

                    </div>

                  </div>


                  <div className="separator">

                    ↔

                  </div>


                  <div className="object">

                    <div className="object-name">

                      {object2.name ||
                        "UNKNOWN OBJECT"}

                    </div>

                    <div className="norad">

                      NORAD{" "}

                      {object2.noradId ||
                        "--"}

                    </div>

                  </div>

                </div>


                {/* =========================================
                    ORBITAL TELEMETRY
                    ========================================= */}

                <div className="telemetry-grid">

                  <div>

                    <span>
                      MISS DISTANCE
                    </span>

                    <strong>

                      {formatDistance(
                        approach.missDistanceKm
                      )}

                    </strong>

                  </div>


                  <div>

                    <span>
                      RELATIVE VELOCITY
                    </span>

                    <strong>

                      {Number.isFinite(
                        approach.relativeVelocityKms
                      )
                        ? `${approach.relativeVelocityKms.toFixed(
                            3
                          )} km/s`
                        : "--"}

                    </strong>

                  </div>


                  <div>

                    <span>
                      TIME TO TCA
                    </span>

                    <strong>

                      {formatTimeToTCA(
                        approach.timeToClosestApproachSeconds
                      )}

                    </strong>

                  </div>

                </div>


                {/* =========================================
                    AI ANALYSIS
                    ========================================= */}

                <div className="ai-analysis">

                  <div className="ai-analysis-header">

                    <span>
                      AI PREDICTION
                    </span>

                    <strong>
                      {predictionLevel}
                    </strong>

                  </div>


                  <div className="ai-confidence">

                    <span>
                      MODEL CONFIDENCE
                    </span>

                    <strong>
                      {formatConfidence(
                        ai.confidence
                      )}
                    </strong>

                  </div>


                  {/* =======================================
                      AI FEATURES
                      ======================================= */}

                  <div className="ai-features">

                    <div>

                      <span>
                        DISTANCE RISK
                      </span>

                      <strong>
                        {features.distanceRisk ??
                          "--"}
                      </strong>

                    </div>


                    <div>

                      <span>
                        VELOCITY RISK
                      </span>

                      <strong>
                        {features.velocityRisk ??
                          "--"}
                      </strong>

                    </div>


                    <div>

                      <span>
                        TIME RISK
                      </span>

                      <strong>
                        {features.timeRisk ??
                          "--"}
                      </strong>

                    </div>


                    <div>

                      <span>
                        ORBITAL RISK
                      </span>

                      <strong>
                        {features.orbitalRisk ??
                          "--"}
                      </strong>

                    </div>

                  </div>


                  {/* =======================================
                      AI FACTORS
                      ======================================= */}

                  {Array.isArray(
                    ai.factors
                  ) &&
                    ai.factors.length >
                      0 && (

                      <div className="ai-factors">

                        <div className="ai-factors-title">

                          PREDICTION FACTORS

                        </div>

                        {ai.factors.map(
                          (
                            factor,
                            factorIndex
                          ) => (

                            <div
                              className="ai-factor"
                              key={
                                factorIndex
                              }
                            >

                              <span>
                                •
                              </span>

                              <span>
                                {factor}
                              </span>

                            </div>

                          )
                        )}

                      </div>

                    )}

                </div>


                {/* =========================================
                    TCA
                    ========================================= */}

                <div className="tca-row">

                  TCA{" "}

                  {approach.tca
                    ? new Date(
                        approach.tca
                      ).toLocaleString()
                    : "--"}

                </div>


                {/* =========================================
                    TRACK EVENT
                    ========================================= */}

                <button
                  className="track-button"
                  onClick={() =>
                    trackEvent(event)
                  }
                >

                  TRACK EVENT

                </button>

              </div>
            );
          }
        )}

      </div>

    </div>
  );
};

export default MissionControl;
